import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();
const { fontFamily: inter } = loadInter();
const { fontFamily: robotoMono } = loadRobotoMono();



export type TypographicBeatProps = Record<string, any>;

const TypographicBeat: React.FC<TypographicBeatProps> = ({
  backgroundColor = "#0A1136",
  transparentBackground = false,
  durationInSeconds = 5,
  fontFamily = "Space Grotesk",
  items = [
    { text: "1", color: "#FFFFFF" },
    { text: "+", color: "#F4C231" },
    { text: "1", color: "#FFFFFF" },
    { text: "=", color: "#02A5EC" },
    { text: "2", color: "#45C58C" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const fontMap: Record<string, string> = {
    "Space Grotesk": spaceGrotesk,
    Inter: inter,
    "Roboto Mono": robotoMono,
  };
  const activeFont = fontMap[fontFamily] || spaceGrotesk;

  // Master container drift to keep the scene alive
  const masterScale = interpolate(frame, [0, fps * durationInSeconds], [1, 1.05]);

  const getCharStyle = (index: number, isLast: boolean): React.CSSProperties => {
    const staggerDelay = 15;
    const startFrame = staggerDelay + index * 10;
    const localFrame = frame - startFrame;

    // Rule: Fully hidden before entrance
    if (localFrame < 0) {
      return { opacity: 0, transition: "none" };
    }

    // Give the final result element a slightly heavier impact
    const stiffness = isLast ? 350 : 250;
    const damping = isLast ? 10 : 12;

    const scale = spring({
      fps,
      frame: localFrame,
      config: { stiffness, damping, mass: 1 },
    });

    const opacity = interpolate(localFrame, [0, 4], [0, 1], {
      extrapolateRight: "clamp",
    });

    const yOffset = interpolate(localFrame, [0, 15], [80 * s, 0], {
      extrapolateRight: "clamp",
    });

    // Alternating rotation directions for the initial pop-in
    const rotDir = index % 2 === 0 ? 1 : -1;
    const rotate = interpolate(localFrame, [0, 15], [20 * rotDir, 0], {
      extrapolateRight: "clamp",
    });

    return {
      opacity,
      transform: `translateY(${yOffset}px) scale(${scale}) rotate(${rotate}deg)`,
      transition: "none",
      display: "inline-block",
    };
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: activeFont,
        overflow: "hidden",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          gap: `${50 * s}px`,
          alignItems: "center",
          justifyContent: "center",
          transform: `scale(${masterScale})`,
          transition: "none",
        }}
      >
        {items.map((item, index) => {
          const isLast = index === items.length - 1;
          return (
            <div
              key={index}
              style={{
                fontSize: `${400 * s}px`,
                fontWeight: 800,
                color: item.color,
                lineHeight: 1,
                ...getCharStyle(index, isLast),
              }}
            >
              {item.text}
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default TypographicBeat;